8	namespace amr_dispatcher_core::planning {
9	namespace {
10	
11	// 8 邻域方向（顺时针，自正北起）：N, NE, E, SE, S, SW, W, NW。
12	// Zhang-Suen 的 P2..P9 与剪枝的度数统计共用这一顺序。
13	constexpr int kDRow[8] = {-1, -1, 0, 1, 1, 1, 0, -1};
14	constexpr int kDCol[8] = {0, 1, 1, 1, 0, -1, -1, -1};
15	
16	// 受保护判定的欧式距离阈值（像素）：站点停靠位通常经正交投影落在骨架
17	// 附近，1.5 像素（默认 0.075m）容差足以吸收亚像素舍入。
18	constexpr double kProtectedDistancePx = 1.5;
19	
20	// 骨架像素坐标（整数栅格）。
21	struct Pixel {
22	  int col = 0;
23	  int row = 0;
24	};
25	
26	// 8 邻域内相邻骨架像素数，即剪枝算法中的"度数"。
27	int Degree(const BinaryGrid& grid, int col, int row) {
28	  int count = 0;
29	  for (int i = 0; i < 8; ++i) {
30	    if (grid.GetValue(col + kDCol[i], row + kDRow[i])) {
31	      ++count;
32	    }
33	  }
34	  return count;
35	}
36	
37	// 8 邻域环上的连通组数（P2..P9,P2 环状序列中 0→1 跳变次数）：
38	//   0 = 无邻居，1 = 端点 / 单组，2 = 线段点，>= 3 = 分叉点。
39	// 与裸度数相比，组数不会把"紧邻正交交叉点的直线像素"（其度数也 >= 3）
40	// 误判为分叉，是像素骨架上更稳健的分叉判据。
41	int CrossingNumber(const BinaryGrid& grid, int col, int row) {
42	  int neighbors[8];
43	  int B = 0;
44	  for (int i = 0; i < 8; ++i) {
45	    neighbors[i] = grid.GetValue(col + kDCol[i], row + kDRow[i]) ? 1 : 0;
46	    B += neighbors[i];
47	  }
48	  if (B == 0) {
49	    return 0;
50	  }
51	  if (B == 8) {
52	    return 1;  // 完全被包围：单一连通组（防御分支，1 像素宽骨架不会出现）
53	  }
54	  int groups = 0;
55	  for (int i = 0; i < 8; ++i) {
56	    if (!neighbors[i] && neighbors[(i + 1) % 8]) {
57	      ++groups;
58	    }
59	  }
60	  return groups;
61	}
62	
63	// 剪除分支后，停止点 S 的剩余邻居在 4 邻接（网格意义）下是否构成单一
64	// 连通组。成立时说明 S 仅因被剪掉的分支而呈现为"分叉"——本体是主线上的
65	// 冗余凸起像素（1 像素宽骨架的正交 T 接合处常见），若不一并剪除会在主干
66	// 上留下 1 像素毛刺伪影。真正的 Y / T / 十字分叉点剩余邻居彼此不相邻，
67	// 返回 false 得以保留。
68	bool NeighborsSingleFourConnected(const BinaryGrid& grid, int col, int row) {
69	  std::vector<Pixel> neighbors;
70	  for (int i = 0; i < 8; ++i) {
71	    if (grid.GetValue(col + kDCol[i], row + kDRow[i])) {
72	      neighbors.push_back({col + kDCol[i], row + kDRow[i]});
73	    }
74	  }
75	  if (neighbors.size() <= 1) {
76	    return true;
77	  }
78	  // 在邻居像素集合上做 4 邻接连通性 BFS。
79	  std::vector<uint8_t> visited(neighbors.size(), 0);
80	  std::vector<size_t> stack{0};
81	  visited[0] = 1;
82	  size_t reached = 1;
83	  while (!stack.empty()) {
84	    const size_t index = stack.back();
85	    stack.pop_back();
86	    for (size_t j = 0; j < neighbors.size(); ++j) {
87	      if (visited[j]) {
88	        continue;
89	      }
90	      const int dc = neighbors[index].col - neighbors[j].col;
91	      const int dr = neighbors[index].row - neighbors[j].row;
92	      if ((dc == 0 && (dr == 1 || dr == -1)) ||
93	          (dr == 0 && (dc == 1 || dc == -1))) {
94	        visited[j] = 1;
95	        stack.push_back(j);
96	        ++reached;
97	      }
98	    }
99	  }
100	  return reached == neighbors.size();
101	}
102	
103	// 分支是否受保护：任一像素与某保护点欧式距离 < 1.5 像素即豁免。
104	bool IsProtectedBranch(const std::vector<Pixel>& branch,
105	                       const std::vector<PixelCoord>& protected_points) {
106	  for (const Pixel& pixel : branch) {
107	    for (const PixelCoord& point : protected_points) {
108	      const double d_col = static_cast<double>(pixel.col) - point.col;
109	      const double d_row = static_cast<double>(pixel.row) - point.row;
110	      if (d_col * d_col + d_row * d_row <
111	          kProtectedDistancePx * kProtectedDistancePx) {
112	        return true;
113	      }
114	    }
115	  }
116	  return false;
117	}
118	
119	}  // namespace
120	
121	BinaryGrid ZhangSuenThinning(const BinaryGrid& grid) {
122	  BinaryGrid result = grid;
123	  if (result.width == 0 || result.height == 0) {
124	    return result;
125	  }
126	
127	  bool changed = true;
128	  while (changed) {
129	    changed = false;
130	    for (int step = 0; step < 2; ++step) {
131	      // 先收集本轮待删除像素，再统一置 0 —— 保证子步内所有判定基于同一
132	      // 快照（Zhang-Suen 的标准同步语义）。
133	      std::vector<Pixel> to_remove;
134	      for (uint32_t row = 0; row < result.height; ++row) {
135	        for (uint32_t col = 0; col < result.width; ++col) {
136	          const int c = static_cast<int>(col);
137	          const int r = static_cast<int>(row);
138	          if (!result.GetValue(c, r)) {
139	            continue;
140	          }
141	          // P2..P9（自正北顺时针），B 为邻域内骨架像素总数。
142	          int neighbors[8];
143	          int B = 0;
144	          for (int i = 0; i < 8; ++i) {
145	            neighbors[i] = result.GetValue(c + kDCol[i], r + kDRow[i]) ? 1 : 0;
146	            B += neighbors[i];
147	          }
148	          if (B < 2 || B > 6) {
149	            continue;  // 孤立点与骨架内部点均不删除
150	          }
151	          // A：P2..P9,P2 环状序列中 0→1 跳变次数，==1 保证不切断连通性。
152	          int A = 0;
153	          for (int i = 0; i < 8; ++i) {
154	            if (!neighbors[i] && neighbors[(i + 1) % 8]) {
155	              ++A;
156	            }
157	          }
158	          if (A != 1) {
159	            continue;
160	          }
161	          bool condition = false;
162	          if (step == 0) {
163	            // 子步 1：P2*P4*P6 == 0 且 P4*P6*P8 == 0
164	            condition = (neighbors[0] * neighbors[2] * neighbors[4] == 0) &&
165	                        (neighbors[2] * neighbors[4] * neighbors[6] == 0);
166	          } else {
167	            // 子步 2：P2*P4*P8 == 0 且 P2*P6*P8 == 0
168	            condition = (neighbors[0] * neighbors[2] * neighbors[6] == 0) &&
169	                        (neighbors[0] * neighbors[4] * neighbors[6] == 0);
170	          }
171	          if (condition) {
172	            to_remove.push_back({c, r});
173	          }
174	        }
175	      }
176	      if (!to_remove.empty()) {
177	        changed = true;
178	        for (const Pixel& pixel : to_remove) {
179	          result.SetValue(pixel.col, pixel.row, 0);
180	        }
181	      }
182	    }
183	  }
184	  return result;
185	}
186	
187	BinaryGrid PruneSkeletonProtected(const BinaryGrid& skeleton,
188	                                  const std::vector<PixelCoord>& protected_points,
189	                                  const PruneConfig& config) {
190	  BinaryGrid result = skeleton;
191	  if (result.width == 0 || result.height == 0) {
192	    return result;
193	  }
194	  const double resolution = config.resolution > 0.0 ? config.resolution : 0.05;
195	
196	  bool changed = true;
197	  while (changed) {
198	    changed = false;
199	    // 每轮重新扫描端点：上一轮剪除会改变度数，端点集合随之变化。
200	    for (uint32_t row = 0; row < result.height; ++row) {
201	      for (uint32_t col = 0; col < result.width; ++col) {
202	        const int start_col = static_cast<int>(col);
203	        const int start_row = static_cast<int>(row);
204	        // 端点在处理时即时复核：同一轮里它可能已被先前的剪除删除。
205	        if (!result.GetValue(start_col, start_row) ||
206	            Degree(result, start_col, start_row) != 1) {
207	          continue;
208	        }
209	
210	        // 从端点向内追踪分支：visited 记录分支像素（端点起，不含停止点）。
211	        std::vector<Pixel> visited;
212	        visited.push_back({start_col, start_row});
213	        int prev_col = start_col;
214	        int prev_row = start_row;
215	        // 端点唯一的骨架邻居即为追踪方向。
216	        int cur_col = -1;
217	        int cur_row = -1;
218	        for (int i = 0; i < 8; ++i) {
219	          const int ncol = start_col + kDCol[i];
220	          const int nrow = start_row + kDRow[i];
221	          if (result.GetValue(ncol, nrow)) {
222	            cur_col = ncol;
223	            cur_row = nrow;
224	            break;
225	          }
226	        }
227	
228	        bool reached_junction = false;
229	        bool reached_other_end = false;
230	        const size_t max_steps =
231	            static_cast<size_t>(result.width) * result.height + 1;
232	        while (visited.size() <= max_steps) {
233	          // 分叉判据用连通组数而非裸度数：紧邻正交交叉点的直线像素（如 T
234	          // 接合处主干上的 (15,3)）8 邻域裸度数也 >= 3，若按裸度数判定
235	          // 会在剪除后于主干上残留 1 像素凸起伪影。
236	          const int crossings = CrossingNumber(result, cur_col, cur_row);
237	          if (crossings >= 3) {
238	            reached_junction = true;
239	            break;
240	          }
241	          if (crossings <= 1) {
242	            // 追踪到另一个端点：整条线段无分叉锚点（例如孤立短线段），
243	            // 不属于"死胡同毛刺"，跳过不剪，避免误删整个连通分量。
244	            reached_other_end = true;
245	            break;
246	          }
247	          // 连通组数 == 2：分支中段，继续沿非来向邻居推进。
248	          visited.push_back({cur_col, cur_row});
249	          for (int i = 0; i < 8; ++i) {
250	            const int ncol = cur_col + kDCol[i];
251	            const int nrow = cur_row + kDRow[i];
252	            if ((ncol != prev_col || nrow != prev_row) &&
253	                result.GetValue(ncol, nrow)) {
254	              prev_col = cur_col;
255	              prev_row = cur_row;
256	              cur_col = ncol;
257	              cur_row = nrow;
258	              break;
259	            }
260	          }
261	        }
262	        if (!reached_junction || reached_other_end) {
263	          continue;
264	        }
265	
266	        const double branch_length_m =
267	            static_cast<double>(visited.size()) * resolution;
268	        if (!(branch_length_m < config.min_branch_length_m)) {
269	          continue;  // 长分支保留
270	        }
271	        // 受保护分支（承载站点）强制豁免，不可剪除。
272	        if (IsProtectedBranch(visited, protected_points)) {
273	          continue;
274	        }
275	        // 剪除短毛刺：分支像素全部置 0，分叉点保留。
276	        for (const Pixel& pixel : visited) {
277	          result.SetValue(pixel.col, pixel.row, 0);
278	        }
279	        // 冗余停止点清理：T 接合处，停止点 S 常因被剪分支才呈现为"分叉"
280	        // （其邻居经 4 邻接连通后实为主干线的一段）。分支剪除后 S 的剩余
281	        // 邻居若构成单一连通组，S 即为主干上的冗余凸起，一并剪除以免留
282	        // 下 1 像素伪影；真正的 Y / T / 十字分叉点剩余邻居彼此不相邻，
283	        // 得以保留。受保护点附近的停止点同样豁免。
284	        if (!IsProtectedBranch({{cur_col, cur_row}}, protected_points) &&
285	            NeighborsSingleFourConnected(result, cur_col, cur_row)) {
286	          result.SetValue(cur_col, cur_row, 0);
287	        }
288	        changed = true;
289	      }
290	    }
291	  }
292	  return result;
293	}
294	
295	}  // namespace amr_dispatcher_core::planning
