16	BinaryGrid MakeGrid(uint32_t width, uint32_t height) {
17	  BinaryGrid grid;
18	  grid.width = width;
19	  grid.height = height;
20	  grid.data.assign(static_cast<size_t>(width) * static_cast<size_t>(height), 0);
21	  return grid;
22	}
