24	// 将 [col0, col1] × [row0, row1] 矩形区域置为可通行 (1)。
25	void FillRect(BinaryGrid& grid, int col0, int row0, int col1, int row1) {
26	  for (int row = row0; row <= row1; ++row) {
27	    for (int col = col0; col <= col1; ++col) {
28	      grid.SetValue(col, row, 1);
29	    }
30	  }
31	}
