33	int CountSkeleton(const BinaryGrid& grid) {
34	  int count = 0;
35	  for (uint32_t row = 0; row < grid.height; ++row) {
36	    for (uint32_t col = 0; col < grid.width; ++col) {
37	      if (grid.GetValue(static_cast<int>(col), static_cast<int>(row))) {
38	        ++count;
39	      }
40	    }
41	  }
42	  return count;
43	}
44	
45	// 8 连通连通分量个数（用于校验骨架连续不断裂）。
46	int CountComponents(const BinaryGrid& grid) {
47	  std::vector<uint8_t> visited(grid.data.size(), 0);
48	  int components = 0;
49	  for (uint32_t start_row = 0; start_row < grid.height; ++start_row) {
50	    for (uint32_t start_col = 0; start_col < grid.width; ++start_col) {
51	      const size_t start_index =
52	          static_cast<size_t>(start_row) * grid.width + start_col;
53	      if (!grid.GetValue(static_cast<int>(start_col),
54	                         static_cast<int>(start_row)) ||
55	          visited[start_index]) {
56	        continue;
57	      }
58	      ++components;
59	      std::queue<std::pair<int, int>> bfs;
60	      bfs.emplace(static_cast<int>(start_col), static_cast<int>(start_row));
61	      visited[start_index] = 1;
62	      while (!bfs.empty()) {
63	        const auto [col, row] = bfs.front();
64	        bfs.pop();
65	        for (int drow = -1; drow <= 1; ++drow) {
66	          for (int dcol = -1; dcol <= 1; ++dcol) {
67	            if (drow == 0 && dcol == 0) {
68	              continue;
69	            }
70	            const int ncol = col + dcol;
71	            const int nrow = row + drow;
72	            if (!grid.IsValidPixel(ncol, nrow) ||
73	                !grid.GetValue(ncol, nrow)) {
74	              continue;
75	            }
76	            const size_t index =
77	                static_cast<size_t>(nrow) * grid.width +
78	                static_cast<size_t>(ncol);
79	            if (visited[index]) {
80	              continue;
81	            }
82	            visited[index] = 1;
83	            bfs.emplace(ncol, nrow);
84	          }
85	        }
86	      }
87	    }
88	  }
89	  return components;
90	}
91	
92	// 是否存在 2×2 全为骨架像素的实心块（1 像素宽骨架不应出现）。
93	bool Has2x2Block(const BinaryGrid& grid) {
94	  if (grid.width < 2 || grid.height < 2) {
95	    return false;
96	  }
97	  for (uint32_t row = 0; row + 1 < grid.height; ++row) {
98	    for (uint32_t col = 0; col + 1 < grid.width; ++col) {
99	      const int c = static_cast<int>(col);
100	      const int r = static_cast<int>(row);
101	      if (grid.GetValue(c, r) && grid.GetValue(c + 1, r) &&
102	          grid.GetValue(c, r + 1) && grid.GetValue(c + 1, r + 1)) {
103	        return true;
104	      }
105	    }
106	  }
107	  return false;
108	}
109	
110	// 细化只允许移除像素：输出为输入的子集。
111	bool IsSubset(const BinaryGrid& candidate, const BinaryGrid& source) {
112	  if (candidate.width != source.width ||
113	      candidate.height != source.height) {
114	    return false;
115	  }
116	  for (uint32_t row = 0; row < source.height; ++row) {
117	    for (uint32_t col = 0; col < source.width; ++col) {
118	      const int c = static_cast<int>(col);
119	      const int r = static_cast<int>(row);
120	      if (candidate.GetValue(c, r) && !source.GetValue(c, r)) {
121	        return false;
122	      }
123	    }
124	  }
125	  return true;
126	}
127	
128	// 8 邻域内相邻骨架像素数（即剪枝算法中的"度数"）。
129	int Degree(const BinaryGrid& grid, int col, int row) {
130	  int count = 0;
131	  for (int drow = -1; drow <= 1; ++drow) {
132	    for (int dcol = -1; dcol <= 1; ++dcol) {
133	      if (drow == 0 && dcol == 0) {
134	        continue;
135	      }
136	      if (grid.GetValue(col + dcol, row + drow)) {
137	        ++count;
138	      }
139	    }
140	  }
141	  return count;
142	}
