145	// 用例 1: 细化提取直走廊 —— 5 像素宽长走廊细化为 1 像素宽居中骨架线
146	// ---------------------------------------------------------------------------
147	
148	TEST(SkeletonExtractorTest, StraightCorridor_ThinsToCenteredOnePixelLine) {
149	  BinaryGrid corridor = MakeGrid(20, 5);
150	  FillRect(corridor, 0, 0, 19, 4);  // 5 像素宽、20 像素长的直走廊
151	
152	  const BinaryGrid skeleton = ZhangSuenThinning(corridor);
153	
154	  ASSERT_EQ(skeleton.width, 20u);
155	  ASSERT_EQ(skeleton.height, 5u);
156	  EXPECT_TRUE(IsSubset(skeleton, corridor));
157	
158	  // 骨架是一条连通的单像素线，不存在 2×2 实心块。
159	  EXPECT_EQ(CountComponents(skeleton), 1);
160	  EXPECT_FALSE(Has2x2Block(skeleton));
161	
162	  // 骨架居中：全部像素位于中心行 row=2 附近（上下各留 1 像素余量）。
163	  int min_row = 99;
164	  int max_row = -1;
165	  int min_col = 99;
166	  int max_col = -1;
167	  int count = 0;
168	  for (uint32_t row = 0; row < skeleton.height; ++row) {
169	    for (uint32_t col = 0; col < skeleton.width; ++col) {
170	      if (!skeleton.GetValue(static_cast<int>(col),
171	                             static_cast<int>(row))) {
172	        continue;
173	      }
174	      ++count;
175	      min_row = std::min(min_row, static_cast<int>(row));
176	      max_row = std::max(max_row, static_cast<int>(row));
177	      min_col = std::min(min_col, static_cast<int>(col));
178	      max_col = std::max(max_col, static_cast<int>(col));
179	    }
180	  }
181	  EXPECT_GE(min_row, 1);
182	  EXPECT_LE(max_row, 3);
183	  EXPECT_EQ(max_row - min_row, 0) << "骨架应为 1 像素宽（单行）";
184	
185	  // 长度保持：横向跨度与像素数一致（连续无断点）。
186	  // 注：经典 Zhang-Suen 会修剪自由端的端帽像素（20 像素长走廊收敛为
187	  // 15 像素骨架线），这里按 >=70% 原长度校验。
188	  EXPECT_EQ(count, max_col - min_col + 1);
189	  EXPECT_GE(count, 14);
190	  EXPECT_LE(count, 20);
191	  for (int col = min_col; col <= max_col; ++col) {
192	    int column_sum = 0;
193	    for (uint32_t row = 0; row < skeleton.height; ++row) {
194	      column_sum += skeleton.GetValue(col, static_cast<int>(row)) ? 1 : 0;
195	    }
196	    EXPECT_EQ(column_sum, 1) << "col=" << col;
197	  }
198	}
