250	// 用例 3: 十字路口骨架提取 —— 保留中心交叉点与 4 个对称分支
251	// ---------------------------------------------------------------------------
252	
253	TEST(SkeletonExtractorTest, CrossJunction_CenterJunctionWithFourBranches) {
254	  BinaryGrid cross = MakeGrid(15, 15);
255	  FillRect(cross, 0, 5, 14, 9);  // 水平带：row 5..9
256	  FillRect(cross, 5, 0, 9, 14);  // 垂直带：col 5..9
257	
258	  const BinaryGrid skeleton = ZhangSuenThinning(cross);
259	
260	  EXPECT_TRUE(IsSubset(skeleton, cross));
261	  EXPECT_EQ(CountComponents(skeleton), 1);
262	  EXPECT_FALSE(Has2x2Block(skeleton));
263	
264	  // 中心交叉点保留：(7,7) 是两臂中心线的交点。
265	  EXPECT_EQ(skeleton.GetValue(7, 7), 1);
266	
267	  // 分叉点（度数 >= 3）聚簇在中心交叉区域，端点（度数 == 1）恰好 4 个。
268	  // 注：8 邻域下正交十字交叉处，中心点及其上下左右紧邻像素都会呈现
269	  // 度数 >= 3，因此分叉像素是一小簇而非单点——全部落在中心 3×3 内。
270	  int endpoints = 0;
271	  int junctions = 0;
272	  for (uint32_t row = 0; row < skeleton.height; ++row) {
273	    for (uint32_t col = 0; col < skeleton.width; ++col) {
274	      if (!skeleton.GetValue(static_cast<int>(col),
275	                             static_cast<int>(row))) {
276	        continue;
277	      }
278	      const int degree =
279	          Degree(skeleton, static_cast<int>(col), static_cast<int>(row));
280	      if (degree == 1) {
281	        ++endpoints;
282	      } else if (degree >= 3) {
283	        ++junctions;
284	        EXPECT_GE(col, 6u) << "分叉像素应聚簇于中心";
285	        EXPECT_LE(col, 8u) << "分叉像素应聚簇于中心";
286	        EXPECT_GE(row, 6u) << "分叉像素应聚簇于中心";
287	        EXPECT_LE(row, 8u) << "分叉像素应聚簇于中心";
288	      }
289	    }
290	  }
291	  EXPECT_GE(junctions, 1) << "中心应存在分叉点";
292	  EXPECT_EQ(endpoints, 4) << "4 个对称分支各有一个端点";
293	
294	  // 4 个分支均自中心 (7,7) 向四个方向延伸。
295	  bool north = false;
296	  bool south = false;
297	  bool east = false;
298	  bool west = false;
299	  for (int row = 0; row <= 14; ++row) {
300	    if (skeleton.GetValue(7, row) && row <= 2) {
301	      north = true;
302	    }
303	    if (skeleton.GetValue(7, row) && row >= 9) {
304	      south = true;
305	    }
306	  }
307	  for (int col = 0; col <= 14; ++col) {
308	    if (skeleton.GetValue(col, 7) && col <= 2) {
309	      west = true;
310	    }
311	    if (skeleton.GetValue(col, 7) && col >= 10) {
312	      east = true;
313	    }
314	  }
315	  EXPECT_TRUE(north);
316	  EXPECT_TRUE(south);
317	  EXPECT_TRUE(east);
318	  EXPECT_TRUE(west);
319	}
