336	// 用例 4: 短毛刺无保护剪除 —— 无保护点时毛刺被清除，主干道完好
337	// ---------------------------------------------------------------------------
338	
339	TEST(SkeletonExtractorTest, ShortBristleUnprotected_PrunedMainLineIntact) {
340	  const BinaryGrid corridor = MakeCorridorWithBristle();
341	  const BinaryGrid skeleton = ZhangSuenThinning(corridor);
342	
343	  // 细化后毛刺分支确实存在：(15,3)..(15,7) 共 5 个像素挂在主干上。
344	  ASSERT_EQ(skeleton.GetValue(15, 7), 1);
345	  ASSERT_EQ(skeleton.GetValue(15, 6), 1);
346	  ASSERT_EQ(skeleton.GetValue(15, 5), 1);
347	  ASSERT_EQ(skeleton.GetValue(15, 4), 1);
348	  ASSERT_EQ(skeleton.GetValue(15, 3), 1);
349	  ASSERT_EQ(skeleton.GetValue(15, 2), 1) << "分叉点位于主干中心线";
350	  const int before = CountSkeleton(skeleton);
351	
352	  PruneConfig config;  // min_branch_length_m = 0.5, resolution = 0.05
353	  const BinaryGrid pruned =
354	      PruneSkeletonProtected(skeleton, {}, config);
355	
356	  // 短毛刺（0.25m < 0.5m，无保护）被完整剪除。
357	  EXPECT_EQ(pruned.GetValue(15, 7), 0);
358	  EXPECT_EQ(pruned.GetValue(15, 6), 0);
359	  EXPECT_EQ(pruned.GetValue(15, 5), 0);
360	  EXPECT_EQ(pruned.GetValue(15, 4), 0);
361	  EXPECT_EQ(pruned.GetValue(15, 3), 0);
362	  EXPECT_EQ(CountSkeleton(pruned), before - 5) << "只应剪除毛刺的 5 个像素";
363	
364	  // 主干道完好：分叉点并入主干，仍为单一连通骨架。
365	  EXPECT_EQ(pruned.GetValue(15, 2), 1);
366	  EXPECT_EQ(CountComponents(pruned), 1);
367	  int main_line_count = 0;
368	  for (int col = 0; col < 30; ++col) {
369	    main_line_count += pruned.GetValue(col, 2) ? 1 : 0;
370	  }
371	  EXPECT_GE(main_line_count, 25) << "主干中心线应基本完好";
372	}
373	
374	// ---------------------------------------------------------------------------
375	// 用例 5: 保护点豁免剪除 —— 站点位于短毛刺末端时，分支强制完整保留
376	// ---------------------------------------------------------------------------
377	
378	TEST(SkeletonExtractorTest, ShortBristleWithProtectedPoint_ExemptFromPruning) {
379	  const BinaryGrid corridor = MakeCorridorWithBristle();
380	  const BinaryGrid skeleton = ZhangSuenThinning(corridor);
381	  ASSERT_EQ(skeleton.GetValue(15, 7), 1);
382	  ASSERT_EQ(skeleton.GetValue(15, 6), 1);
383	  ASSERT_EQ(skeleton.GetValue(15, 5), 1);
384	  ASSERT_EQ(skeleton.GetValue(15, 4), 1);
385	  ASSERT_EQ(skeleton.GetValue(15, 3), 1);
