// 评审用临时边界用例探针（不入库）。
#include "amr_dispatcher_core/planning/skeleton_extractor.hpp"

#include <cstdio>
#include <vector>

using namespace amr_dispatcher_core::planning;

namespace {

BinaryGrid MakeGrid(uint32_t w, uint32_t h) {
  BinaryGrid g;
  g.width = w;
  g.height = h;
  g.data.assign(static_cast<size_t>(w) * h, 0);
  return g;
}

void Set(BinaryGrid& g, int c, int r) { g.SetValue(c, r, 1); }

int Count(const BinaryGrid& g) {
  int n = 0;
  for (uint32_t r = 0; r < g.height; ++r)
    for (uint32_t c = 0; c < g.width; ++c)
      if (g.GetValue((int)c, (int)r)) ++n;
  return n;
}

int Degree(const BinaryGrid& g, int c, int r) {
  int d = 0;
  for (int dr = -1; dr <= 1; ++dr)
    for (int dc = -1; dc <= 1; ++dc)
      if ((dc || dr) && g.GetValue(c + dc, r + dr)) ++d;
  return d;
}

}  // namespace

int main() {
  // 用例 A：纯环（无端点）—— 剪枝不应挂起、不应删任何像素。
  {
    BinaryGrid g = MakeGrid(11, 11);
    for (int i = 2; i <= 8; ++i) {
      Set(g, i, 2); Set(g, i, 8); Set(g, 2, i); Set(g, 8, i);
    }
    PruneConfig cfg;
    const BinaryGrid out = PruneSkeletonProtected(g, {}, cfg);
    std::printf("[A ring] in=%d out=%d (expect unchanged) -> %s\n", Count(g),
                Count(out), Count(g) == Count(out) ? "OK" : "FAIL");
  }
  // 用例 B：环 + 短茎（lollipop）—— 应不挂起；茎是否剪除只报告结果。
  {
    BinaryGrid g = MakeGrid(15, 11);
    for (int i = 4; i <= 10; ++i) {
      Set(g, i, 2); Set(g, i, 8); Set(g, 4, i); Set(g, 10, i);
    }
    for (int r = 3; r <= 5; ++r) Set(g, 7, r);  // 茎从环顶向下
    Set(g, 7, 1); Set(g, 7, 0);                  // 短茎端点 (7,0)，茎长 ~3px=0.15m
    PruneConfig cfg;
    const BinaryGrid out = PruneSkeletonProtected(g, {}, cfg);
    std::printf("[B lollipop] in=%d out=%d stem_end(7,0)=%d (0=pruned,1=kept)\n",
                Count(g), Count(out), out.GetValue(7, 0));
  }
  // 用例 C：环带两个短毛刺 —— 收敛性：剪一个是否暴露新的可剪分支。
  {
    BinaryGrid g = MakeGrid(15, 15);
    // 方环 3..11
    for (int i = 3; i <= 11; ++i) { Set(g, i, 3); Set(g, i, 11); Set(g, 3, i); Set(g, 11, i); }
    // 毛刺1：从环左边 (3,7) 向左伸出 2px -> (1,7),(2,7)？(2,7) 邻 (3,7)
    Set(g, 2, 7); Set(g, 1, 7);
    // 毛刺2：从环右边 (11,7) 向右 2px
    Set(g, 12, 7); Set(g, 13, 7);
    PruneConfig cfg;
    const BinaryGrid out = PruneSkeletonProtected(g, {}, cfg);
    std::printf("[C ring+2 spurs] in=%d out=%d spur1(1,7)=%d spur2(13,7)=%d\n",
                Count(g), Count(out), out.GetValue(1, 7), out.GetValue(13, 7));
  }
  // 用例 D：细化后的十字再剪枝 —— 分叉簇与 4 臂应完好（长分支豁免）。
  {
    BinaryGrid g = MakeGrid(15, 15);
    for (int r = 5; r <= 9; ++r) for (int c = 0; c <= 14; ++c) Set(g, c, r);
    for (int c = 5; c <= 9; ++c) for (int r = 0; r <= 14; ++r) Set(g, c, r);
    const BinaryGrid skel = ZhangSuenThinning(g);
    PruneConfig cfg;
    const BinaryGrid out = PruneSkeletonProtected(skel, {}, cfg);
    int ends_before = 0, ends_after = 0;
    for (uint32_t r = 0; r < 15; ++r)
      for (uint32_t c = 0; c < 15; ++c) {
        if (skel.GetValue((int)c, (int)r) && Degree(skel, (int)c, (int)r) == 1) ++ends_before;
        if (out.GetValue((int)c, (int)r) && Degree(out, (int)c, (int)r) == 1) ++ends_after;
      }
    std::printf("[D cross prune] skel=%d pruned=%d endpoints %d->%d\n",
                Count(skel), Count(out), ends_before, ends_after);
  }
  // 用例 E：L 弯细化后剪枝 —— 拐角两端长臂不应被剪。
  {
    BinaryGrid g = MakeGrid(20, 20);
    for (int r = 0; r <= 4; ++r) for (int c = 0; c <= 19; ++c) Set(g, c, r);
    for (int r = 0; r <= 19; ++r) for (int c = 0; c <= 4; ++c) Set(g, c, r);
    const BinaryGrid skel = ZhangSuenThinning(g);
    PruneConfig cfg;
    const BinaryGrid out = PruneSkeletonProtected(skel, {}, cfg);
    std::printf("[E L prune] skel=%d pruned=%d (expect equal)\n",
                Count(skel), Count(out));
  }
  // 用例 F：收敛链 —— T 主干上一个短凸起被剪后，停止点清理暴露新端点，
  // 下一轮应继续剪直到稳定（验证 while(changed) 真正迭代）。
  {
    BinaryGrid g = MakeGrid(30, 12);
    // 主干水平 row=6, col 0..29（1px 骨架直接构造，不经细化）
    for (int c = 0; c <= 29; ++c) Set(g, c, 6);
    // 两级阶梯毛刺挂在 col=10：上凸起 (10,5)、再 (11,4)、端点 (12,3)
    // 形状： (10,5)-(11,4)-(12,3) 斜向短枝，总 ~3px
    Set(g, 10, 5); Set(g, 11, 4); Set(g, 12, 3);
    // 另一独立短枝 col=20: (20,5),(20,4) 端点 (20,4)
    Set(g, 20, 5);
    Set(g, 20, 4);
    PruneConfig cfg;
    const BinaryGrid out = PruneSkeletonProtected(g, {}, cfg);
    std::printf("[F chain] in=%d out=%d main(0..29,6)=%d spur_end(12,3)=%d(20,4)=%d\n",
                Count(g), Count(out), out.GetValue(0, 6), out.GetValue(12, 3),
                out.GetValue(20, 4));
  }
  // 用例 G：Zhang-Suen 在 2px 对角毛刺上的单像素宽度保障 + 对角线不误判分叉。
  {
    BinaryGrid g = MakeGrid(12, 12);
    for (int i = 1; i <= 10; ++i) Set(g, i, i);  // 纯对角线
    const BinaryGrid skel = ZhangSuenThinning(g);
    // 对角线上每点度数应为 2（除端点），不应出现 >=3 的假分叉。
    int fake_junction = 0;
    for (uint32_t r = 0; r < 12; ++r)
      for (uint32_t c = 0; c < 12; ++c)
        if (skel.GetValue((int)c, (int)r) && Degree(skel, (int)c, (int)r) >= 3)
          ++fake_junction;
    std::printf("[G diagonal] count=%d fake_junctions=%d\n", Count(skel),
                fake_junction);
  }
  // 用例 H：保护点在分叉点/主干附近（不在毛刺上）——毛刺仍应剪除，
  // 但主干上的保护点附近的停止点清理不得误删主干像素。
  {
    BinaryGrid g = MakeGrid(30, 16);
    for (int r = 0; r <= 4; ++r) for (int c = 0; c <= 29; ++c) Set(g, c, r);
    for (int r = 5; r <= 7; ++r) Set(g, 15, r);  // 毛刺
    const BinaryGrid skel = ZhangSuenThinning(g);
    PruneConfig cfg;
    // 保护点在主干 (10,2)，远离毛刺
    const BinaryGrid out =
        PruneSkeletonProtected(skel, {{10.0, 2.0}}, cfg);
    std::printf("[H protect-on-main] skel=%d pruned=%d bristle(15,7)=%d main(10,2)=%d main(15,2)=%d\n",
                Count(skel), Count(out), out.GetValue(15, 7),
                out.GetValue(10, 2), out.GetValue(15, 2));
  }
  return 0;
}

