  // 但主干上的保护点附近的停止点清理不得误删主干像素。
  {
    BinaryGrid g = MakeGrid(30, 16);
    for (int r = 0; r <= 4; ++r) for (int c = 0; c <= 29; ++c) Set(g, c, r);
    for (int r = 5; r <= 7; ++r) Set(g, 15, r);  // 毛刺
