// 隔离探针：确定斜向毛刺与主干尾段的实际剪枝行为。
#include "amr_dispatcher_core/planning/skeleton_extractor.hpp"
#include <cstdio>

using namespace amr_dispatcher_core::planning;

namespace {
BinaryGrid G(uint32_t w, uint32_t h) {
  BinaryGrid g; g.width = w; g.height = h;
  g.data.assign((size_t)w * h, 0); return g;
}
void S(BinaryGrid& g, int c, int r) { g.SetValue(c, r, 1); }
void Dump(const char* t, const BinaryGrid& g) {
  std::printf("-- %s\n", t);
  for (uint32_t r = 0; r < g.height; ++r) {
    for (uint32_t c = 0; c < g.width; ++c)
      std::putchar(g.GetValue((int)c, (int)r) ? '#' : '.');
    std::putchar('\n');
  }
}
}  // namespace

int main() {
  // 隔离 1：主干 + 斜向阶梯毛刺（无其它端点干扰，主干两端远离）
  {
    BinaryGrid g = G(30, 12);
    for (int c = 0; c <= 29; ++c) S(g, c, 6);
    S(g, 10, 5); S(g, 11, 4); S(g, 12, 3);
    PruneConfig cfg;
    Dump("iso1 in", g);
    Dump("iso1 out", PruneSkeletonProtected(g, {}, cfg));
  }
  // 隔离 2：仅主干 + 正交短毛刺（复现官方用例 4 的原始形态）
  {
    BinaryGrid g = G(30, 12);
    for (int c = 0; c <= 29; ++c) S(g, c, 6);
    S(g, 20, 5); S(g, 20, 4);
    PruneConfig cfg;
    Dump("iso2 in", g);
    Dump("iso2 out", PruneSkeletonProtected(g, {}, cfg));
  }
  // 隔离 3：仅主干（无毛刺）—— 不应剪掉任何东西，即使端点间分支
  // 视扫描方向可能短于阈值
  {
    BinaryGrid g = G(30, 8);
    for (int c = 0; c <= 29; ++c) S(g, c, 6);
    PruneConfig cfg;
    const BinaryGrid out = PruneSkeletonProtected(g, {}, cfg);
    std::printf("iso3 bare main in=%d out=%d (expect equal)\n",
                (int)g.data.size() - (int)g.data.size() + 30, [&]{
                  int n=0; for (uint32_t r=0;r<out.height;++r)
                  for (uint32_t c=0;c<out.width;++c) if (out.GetValue((int)c,(int)r)) ++n;
                  return n; }());
  }
  // 隔离 4：短主干线段（两端点间距 < 阈值，无分叉）—— 不应剪
  {
    BinaryGrid g = G(10, 5);
    for (int c = 2; c <= 7; ++c) S(g, c, 2);
    PruneConfig cfg;
    const BinaryGrid out = PruneSkeletonProtected(g, {}, cfg);
    int n = 0;
    for (uint32_t r = 0; r < out.height; ++r)
      for (uint32_t c = 0; c < out.width; ++c)
        if (out.GetValue((int)c, (int)r)) ++n;
    std::printf("iso4 short segment in=6 out=%d (expect 6)\n", n);
  }
  return 0;
}

