// Step-by-step trace probe: replicate PruneSkeletonProtected's trace on iso2 geometry.
#include "amr_dispatcher_core/planning/safety_space_filter.hpp"
#include <cstdio>
using amr_dispatcher_core::planning::BinaryGrid;
constexpr int kDRow[8] = {-1,-1,0,1,1,1,0,-1};
constexpr int kDCol[8] = {0,1,1,1,0,-1,-1,-1};
int Crossing(const BinaryGrid& g,int col,int row){
  int n[8],B=0; for(int i=0;i<8;++i){n[i]=g.GetValue(col+kDCol[i],row+kDRow[i])?1:0;B+=n[i];}
  if(B==0)return 0; if(B==8)return 1;
  int gr=0; for(int i=0;i<8;++i) if(!n[i]&&n[(i+1)%8]) ++gr; return gr;
}
int main(){
  BinaryGrid g; g.width=30; g.height=12; g.data.assign(30*12u,0);
  for(int c=0;c<=29;++c) g.SetValue(c,6,1);
  g.SetValue(20,5,1); g.SetValue(20,4,1);
  // trace from endpoint (20,4)
  int sc=20, sr=4, prev_c=20, prev_r=4, cur_c=-1, cur_r=-1;
  for(int i=0;i<8;++i){int nc=sc+kDCol[i],nr=sr+kDRow[i]; if(g.GetValue(nc,nr)){cur_c=nc;cur_r=nr;break;}}
  std::printf("start=(%d,%d) first_step cur=(%d,%d)\n", sc,sr,cur_c,cur_r);
  int visited=1;
  for(int step=0; step<20; ++step){
    int cn = Crossing(g,cur_c,cur_r);
    std::printf("step %d: cur=(%d,%d) crossings=%d prev=(%d,%d)\n", step,cur_c,cur_r,cn,prev_c,prev_r);
    if(cn>=3){std::printf("  -> JUNCTION visited=%d\n",visited); break;}
    if(cn<=1){std::printf("  -> OTHER END visited=%d\n",visited); break;}
    ++visited;
    bool moved=false;
    for(int i=0;i<8;++i){
      int nc=cur_c+kDCol[i], nr=cur_r+kDRow[i];
      if((nc!=prev_c||nr!=prev_r)&&g.GetValue(nc,nr)){
        std::printf("  advance i=%d -> (%d,%d)\n", i, nc, nr);
        prev_c=cur_c; prev_r=cur_r; cur_c=nc; cur_r=nr; moved=true; break;
      }
    }
    if(!moved){std::printf("  NO MOVE\n"); break;}
  }
  return 0;
}
